'use client';

import './admin.css';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import {
  Activity, ArrowDownToLine, ArrowUpRight, Bell, Blocks, BookOpen, Check, ChevronDown,
  ChevronRight, CircleHelp, Code2, Command, CreditCard, Database, Eye, FileText, Fingerprint,
  Gauge, Globe2, HardDrive, Image as ImageIcon, LayoutDashboard, LayoutTemplate, LockKeyhole,
  Menu, Monitor, MoreHorizontal, Palette, PanelLeft, Plus, Search, Settings2, ShieldCheck,
  SlidersHorizontal, Sparkles, ToggleLeft, ToggleRight, Trash2, Upload, Users, WandSparkles,
  X, Zap, RefreshCw, Download, ExternalLink, CircleCheck, AlertTriangle, Save, Type, Layers,
  ChartNoAxesCombined, MousePointer2, Paintbrush, FileCode2, CalendarClock, KeyRound
} from 'lucide-react';
import { tools as catalogTools, categoryNames } from '../../lib/catalog';
import { signOut } from 'next-auth/react';

type ModuleId = 'overview'|'theme'|'tools'|'content'|'seo'|'media'|'security'|'monetization'|'system'|'integrations';
type Settings = {
  siteName:string; tagline:string; accent:string; background:string; surface:string; radius:number;
  font:string; headerText:string; footerText:string; metaTitle:string; metaDescription:string;
  canonical:string; robots:string; customCss:string; maintenance:boolean; analyticsId:string;
  adsEnabled:boolean; adsenseId:string; freeDailyLimit:number; maxUploadMb:number;
};
type ToolOverride = { enabled:boolean; name:string; description:string; seoTitle:string; limitMb:number; formats:string };
const STORE_KEY = 'toolixa-command-center-v1';
const defaultSettings:Settings = {
  siteName:'TOOLIXA',tagline:'One workspace. Infinite utility.',accent:'#9b87ff',background:'#08080b',surface:'#121218',radius:16,
  font:'Inter',headerText:'Tools that move at your speed.',footerText:'Built for better workflows.',metaTitle:'TOOLIXA — Online Tools, One Workspace',
  metaDescription:'A privacy-first workspace for image, PDF, text, file, SEO and productivity tools.',canonical:'https://your-domain.example',robots:'index, follow',customCss:'',maintenance:false,analyticsId:'',adsEnabled:false,adsenseId:'',freeDailyLimit:5,maxUploadMb:25
};
const modules:{id:ModuleId;label:string;sub:string;icon:any;count?:string}[] = [
  {id:'overview',label:'Command overview',sub:'System telemetry',icon:LayoutDashboard},
  {id:'theme',label:'Visual theme engine',sub:'Design & templates',icon:Palette,count:'1K+'},
  {id:'tools',label:'Tool commander',sub:'Catalog & controls',icon:Blocks,count:'1.0K'},
  {id:'content',label:'Page & content',sub:'Pages, posts, menus',icon:FileText,count:'800+'},
  {id:'seo',label:'SEO & marketing',sub:'Search & campaigns',icon:ChartNoAxesCombined,count:'500+'},
  {id:'media',label:'Media & storage',sub:'Assets & uploads',icon:HardDrive,count:'400+'},
  {id:'security',label:'User & security',sub:'Access & protection',icon:ShieldCheck,count:'300+'},
  {id:'monetization',label:'Monetization',sub:'Plans & usage limits',icon:CreditCard,count:'300+'},
  {id:'system',label:'System & backups',sub:'Logs & operations',icon:Database,count:'200+'},
  {id:'integrations',label:'Integrations',sub:'APIs & connections',icon:Zap},
];
const baseToolOverrides = () => Object.fromEntries(catalogTools.map(t=>[t.id,{enabled:t.live,name:t.name,description:t.description,seoTitle:`${t.name} | TOOLIXA`,limitMb:25,formats:'JPG, PNG, WEBP'}])) as Record<string,ToolOverride>;
const initialPages = [
  {slug:'/',title:'Home',type:'System page',status:'Published'},
  {slug:'/about',title:'About TOOLIXA',type:'Static page',status:'Draft'},
  {slug:'/contact',title:'Contact',type:'Static page',status:'Draft'},
  {slug:'/privacy',title:'Privacy Policy',type:'Legal page',status:'Draft'},
  {slug:'/terms',title:'Terms of Service',type:'Legal page',status:'Draft'},
];
function cn(...classes:(string|false|undefined|null)[]){return classes.filter(Boolean).join(' ')}
function Field({label,value,onChange,placeholder,type='text'}:{label:string;value:string|number;onChange:(v:string)=>void;placeholder?:string;type?:string}){
 return <label className="cc-field"><span>{label}</span><input type={type} value={value} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></label>
}
function Toggle({value,onChange,label}:{value:boolean;onChange:(v:boolean)=>void;label?:string}){
 return <button type="button" className={cn('cc-toggle',value&&'on')} aria-pressed={value} onClick={()=>onChange(!value)}><span/>{label&&<b>{label}</b>}</button>
}
function Panel({title,description,children,action}:{title:string;description?:string;children:React.ReactNode;action?:React.ReactNode}){
 return <section className="cc-panel"><div className="cc-panel-head"><div><h3>{title}</h3>{description&&<p>{description}</p>}</div>{action}</div>{children}</section>
}
export default function AdminPage(){
 const [active,setActive]=useState<ModuleId>('overview');
 const [settings,setSettings]=useState<Settings>(defaultSettings);
 const [toolOverrides,setToolOverrides]=useState<Record<string,ToolOverride>>({});
 const [query,setQuery]=useState(''); const [category,setCategory]=useState('All categories');
 const [selectedTool,setSelectedTool]=useState(catalogTools.find(t=>t.live)?.id||catalogTools[0].id);
 const [pages,setPages]=useState(initialPages); const [newPageTitle,setNewPageTitle]=useState('');
 const [postTitle,setPostTitle]=useState(''); const [postBody,setPostBody]=useState('');
 const [templates,setTemplates]=useState(['Midnight / Default','Clean / Minimal','Studio / Editorial']);
 const [activeTemplate,setActiveTemplate]=useState('Midnight / Default');
 const [roles,setRoles]=useState([{name:'Super Admin',members:1,permissions:'Full access'},{name:'Editor',members:0,permissions:'Content, media, SEO'},{name:'Blogger',members:0,permissions:'Own posts only'}]);
 const [plans,setPlans]=useState([{name:'Free',price:'0',period:'month',enabled:true},{name:'Pro',price:'4.99',period:'month',enabled:false},{name:'Studio',price:'9.99',period:'month',enabled:false}]);
 const [logs,setLogs]=useState<{time:string;message:string;type:string}[]>([]);
 const [assets,setAssets]=useState<{name:string;size:string;url:string}[]>([]);
 const [toast,setToast]=useState(''); const [mobileNav,setMobileNav]=useState(false); const [mounted,setMounted]=useState(false);
 const [previewMode,setPreviewMode]=useState<'desktop'|'mobile'>('desktop');
 const [persistence,setPersistence]=useState<'checking'|'database'|'local'>('checking');
 const [saving,setSaving]=useState(false);
 useEffect(()=>{
  let cancelled=false;
  const applySnapshot=(s:any)=>{if(!s||typeof s!=='object')return;setSettings({...defaultSettings,...(s.settings||{})});setToolOverrides({...baseToolOverrides(),...(s.toolOverrides||{})});setPages(Array.isArray(s.pages)?s.pages:initialPages);setTemplates(Array.isArray(s.templates)?s.templates:['Midnight / Default','Clean / Minimal','Studio / Editorial']);setActiveTemplate(s.activeTemplate||'Midnight / Default');setRoles(Array.isArray(s.roles)?s.roles:[{name:'Super Admin',members:1,permissions:'Full access'}]);setPlans(Array.isArray(s.plans)?s.plans:[{name:'Free',price:'0',period:'month',enabled:true}]);setLogs(Array.isArray(s.logs)?s.logs:[])};
  try{const raw=localStorage.getItem(STORE_KEY);if(raw)applySnapshot(JSON.parse(raw));}catch{}
  setMounted(true);
  fetch('/api/admin/settings',{cache:'no-store'}).then(async r=>{if(!r.ok)throw new Error('database unavailable');const data=await r.json();if(!cancelled&&data.settings?.commandCenter){applySnapshot(data.settings.commandCenter);setPersistence('database');}}).catch(()=>{if(!cancelled)setPersistence('local')});
  return()=>{cancelled=true};
 },[]);
 const logAction=useCallback((message:string,type='update')=>{setLogs(old=>[{time:new Date().toLocaleString(),message,type},...old].slice(0,100))},[]);
 useEffect(()=>{if(!mounted)return;try{localStorage.setItem(STORE_KEY,JSON.stringify({settings,toolOverrides,pages,templates,activeTemplate,roles,plans,logs}));}catch{}},[mounted,settings,toolOverrides,pages,templates,activeTemplate,roles,plans,logs]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),2800);return()=>clearTimeout(id)},[toast]);
 const updateSetting=<K extends keyof Settings>(key:K,value:Settings[K])=>setSettings(s=>({...s,[key]:value}));
 const visibleTools=useMemo(()=>catalogTools.filter(t=>{
   const o=toolOverrides[t.id]||{enabled:t.live,name:t.name,description:t.description,seoTitle:`${t.name} | TOOLIXA`,limitMb:25,formats:'JPG, PNG, WEBP'};
   return (category==='All categories'||t.category===category)&&`${o.name} ${t.category} ${o.description}`.toLowerCase().includes(query.toLowerCase());
 }),[query,category,toolOverrides]);
 const currentTool=catalogTools.find(t=>t.id===selectedTool)||catalogTools[0];
 const currentOverride=toolOverrides[selectedTool]||{enabled:currentTool.live,name:currentTool.name,description:currentTool.description,seoTitle:`${currentTool.name} | TOOLIXA`,limitMb:25,formats:'JPG, PNG, WEBP'};
 const saveNotice=(message='Settings saved to this browser')=>{logAction(message);setToast(message)};
 const saveConfiguration=async()=>{
  setSaving(true);
  const snapshot={settings,toolOverrides,pages,templates,activeTemplate,roles,plans,logs};
  try{
   const response=await fetch('/api/admin/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({settings:{commandCenter:snapshot}})});
   const result=await response.json().catch(()=>({}));
   if(!response.ok)throw new Error(result.error||'Database save unavailable');
   setPersistence('database');logAction('Configuration saved to PostgreSQL','success');setToast('Configuration saved to database');
  }catch{
   try{localStorage.setItem(STORE_KEY,JSON.stringify(snapshot));setPersistence('local');setToast('Database unavailable — saved to this browser only');}
   catch{setToast('Save failed: browser storage is unavailable')}
  }finally{setSaving(false)}
 };
 const exportBackup=()=>{const data={product:'TOOLIXA COMMAND CENTER',schemaVersion:1,exportedAt:new Date().toISOString(),settings,toolOverrides,pages,templates,activeTemplate,roles,plans,logs};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`toolixa-command-center-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);logAction('Configuration backup exported','backup');setToast('Backup exported')};
 const importBackup=(file?:File)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const d=JSON.parse(String(reader.result));if(!d||d.product!=='TOOLIXA COMMAND CENTER')throw new Error('Not a TOOLIXA backup');setSettings({...defaultSettings,...d.settings});setToolOverrides({...baseToolOverrides(),...(d.toolOverrides||{})});setPages(d.pages||initialPages);setTemplates(d.templates||['Midnight / Default']);setActiveTemplate(d.activeTemplate||'Midnight / Default');setRoles(d.roles||[]);setPlans(d.plans||[]);setLogs(d.logs||[]);setToast('Backup restored in this browser');}catch{setToast('Invalid backup file')} };reader.readAsText(file)};
 const createPage=()=>{if(!newPageTitle.trim()){setToast('Enter a page title first');return}const slug='/'+newPageTitle.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');setPages(p=>[...p,{slug,title:newPageTitle.trim(),type:'Custom page',status:'Draft'}]);logAction(`Created draft page: ${slug}`);setNewPageTitle('');setToast('Draft page created')};
 const addAsset=(file?:File)=>{if(!file)return;const url=URL.createObjectURL(file);setAssets(a=>[{name:file.name,size:file.size>1024*1024?`${(file.size/1024/1024).toFixed(1)} MB`:`${Math.max(1,Math.round(file.size/1024))} KB`,url},...a]);logAction(`Added local preview asset: ${file.name}`);setToast('Asset added for this browser preview')};
 const moduleTitle=modules.find(m=>m.id===active)?.label||'Command overview';
 const themeStyle={'--cc-accent':settings.accent,'--cc-bg':settings.background,'--cc-surface':settings.surface,'--cc-radius':`${settings.radius}px`} as React.CSSProperties;
 return <main className="cc-shell" style={themeStyle}>
  <aside className={cn('cc-sidebar',mobileNav&&'show')}>
   <div className="cc-brand"><div className="cc-brand-mark"><Command size={21}/></div><div><strong>TOOLIXA</strong><small>COMMAND CENTER <span>V3.1</span></small></div><button className="cc-close-nav" onClick={()=>setMobileNav(false)} aria-label="Close menu"><X size={18}/></button></div>
   <div className="cc-workspace"><div className="cc-workspace-icon"><Layers size={16}/></div><div><strong>TOOLIXA Production</strong><small>Workspace / Owner</small></div><ChevronDown size={15}/></div>
   <div className="cc-nav-label">CONTROL SYSTEMS</div>
   <nav className="cc-nav">{modules.map(m=>{const Icon=m.icon;return <button key={m.id} className={cn('cc-nav-item',active===m.id&&'active')} onClick={()=>{setActive(m.id);setMobileNav(false)}}><Icon size={17}/><span>{m.label}</span>{m.count&&<small>{m.count}</small>}</button>})}</nav>
   <div className="cc-sidebar-bottom"><div className="cc-system-state"><span className="cc-live-dot"/><div><strong>{persistence==='database'?'Database mode':persistence==='checking'?'Checking storage':'Local control mode'}</strong><small>{persistence==='database'?'PostgreSQL connected':persistence==='checking'?'Checking server status':'Browser storage fallback'}</small></div><MoreHorizontal size={17}/></div><button className="cc-help" onClick={()=>setToast('Read docs/COMMAND_CENTER_STATUS.md before production use')}><CircleHelp size={16}/> Command Center help <ExternalLink size={13}/></button><div className="cc-user"><div className="cc-avatar">TA</div><div><strong>TOOLIXA Admin</strong><small>Demo workspace</small></div><Settings2 size={17}/></div></div>
  </aside>
  {mobileNav&&<button className="cc-backdrop" onClick={()=>setMobileNav(false)} aria-label="Close navigation"/>}
  <section className="cc-main">
   <header className="cc-topbar"><div className="cc-top-left"><button className="cc-mobile-menu" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Menu size={19}/></button><div className="cc-breadcrumb">TOOLIXA <ChevronRight size={13}/><span>{moduleTitle}</span></div></div><div className="cc-top-right"><div className="cc-env"><span className="cc-live-dot"/> ADMIN CONSOLE</div><button className="cc-top-icon" title="Search" onClick={()=>{setActive('tools');setToast('Tool catalog search is ready')}}><Search size={17}/></button><button className="cc-top-icon" title="Activity" onClick={()=>setActive('system')}><Bell size={17}/></button><button className="cc-top-icon" title="Sign out" onClick={()=>signOut({callbackUrl:'/admin/login'})}><LockKeyhole size={17}/></button><button className="cc-save" onClick={saveConfiguration} disabled={saving}><Save size={15}/> {saving?'Saving…':'Save changes'}</button></div></header>
   <div className="cc-content">
    {active==='overview'&&<>
     <div className="cc-page-intro"><div><div className="cc-kicker"><span className="cc-live-dot"/> SYSTEMS NOMINAL · PREVIEW MODE</div><h1>Command <span>Center</span></h1><p>Your website operations, unified. Configure the experience, inspect the catalog and manage the control plane.</p></div><div className="cc-intro-actions"><button className="cc-btn-secondary" onClick={()=>setActive('theme')}><Paintbrush size={15}/> Customize UI</button><button className="cc-btn-primary" onClick={exportBackup}><ArrowDownToLine size={15}/> Export backup</button></div></div>
     <div className="cc-stats-grid"><Metric icon={Blocks} label="Catalog entries" value="1,040" delta="52 categories"/><Metric icon={ToggleRight} label="Ready-marked tools" value={catalogTools.filter(t=>(toolOverrides[t.id]?.enabled??t.live)).length.toString()} delta="Enable / disable controls"/><Metric icon={Palette} label="Theme status" value="Live preview" delta="Changes apply instantly"/><Metric icon={ShieldCheck} label="Security status" value="Setup required" delta="Auth is not configured" warning/></div>
     <div className="cc-overview-grid"><Panel title="Operations console" description="Jump directly into a control surface."><div className="cc-quick-grid">{modules.slice(1).map(m=>{const Icon=m.icon;return <button className="cc-quick-action" key={m.id} onClick={()=>setActive(m.id)}><span><Icon size={18}/></span><b>{m.label}</b><small>{m.sub}</small><ChevronRight size={15}/></button>})}</div></Panel><div className="cc-stack"><Panel title="Live storefront preview" description="Updates as theme settings change."><div className={`cc-preview-frame ${previewMode==='mobile'?'mobile':''}`}><div className="cc-preview-top"><div className="cc-preview-logo"><span>✦</span>{settings.siteName}</div><div className="cc-preview-links"><span>Tools</span><span>About</span><span>Blog</span></div><span className="cc-preview-pill">Explore tools ↗</span></div><div className="cc-preview-hero"><span>✦ YOUR WORKSPACE</span><h4>{settings.headerText}</h4><p>{settings.tagline}</p><div className="cc-preview-search"><Search size={13}/> Search 1,000+ tools...</div></div><div className="cc-preview-cards"><span/><span/><span/></div></div><div className="cc-preview-controls"><button onClick={()=>setPreviewMode('desktop')} className={cn(previewMode==='desktop'&&'selected')}><Monitor size={14}/> Desktop</button><button onClick={()=>setPreviewMode('mobile')} className={cn(previewMode==='mobile'&&'selected')}><PanelLeft size={14}/> Mobile</button><button onClick={()=>setActive('theme')}>Edit theme <ArrowUpRight size={13}/></button></div></Panel><Panel title="Recent activity" description="Latest changes in this browser workspace."><div className="cc-activity-list">{logs.slice(0,4).map((l,i)=><div className="cc-activity-item" key={i}><span className="cc-activity-icon"><Activity size={14}/></span><div><b>{l.message}</b><small>{l.time}</small></div></div>)}{logs.length===0&&<div className="cc-empty-small">No changes recorded yet. Your actions will appear here.</div>}</div></Panel></div></div>
     <div className="cc-warning-banner"><ShieldCheck size={19}/><div><strong>Pre-production notice</strong><p>Admin routes require a Super Admin session. Configuration can sync to PostgreSQL when DATABASE_URL and Prisma migrations are configured; otherwise the dashboard falls back to this browser. Theme and tool settings still require storefront integration before they affect the public site.</p></div><button onClick={()=>setActive('security')}>Review security <ChevronRight size={15}/></button></div>
    </>}
    {active==='theme'&&<><PageIntro icon={Palette} eyebrow="MODULE 01 / DESIGN SYSTEM" title="Visual theme engine" subtitle="Tune your visual identity with an immediate storefront preview."/><div className="cc-two-col"><div className="cc-stack"><Panel title="Brand identity" description="Global brand and typography controls."><Field label="Site name" value={settings.siteName} onChange={v=>updateSetting('siteName',v)}/><Field label="Tagline" value={settings.tagline} onChange={v=>updateSetting('tagline',v)}/><div className="cc-field-grid"><label className="cc-field"><span>Accent color</span><div className="cc-color-field"><input type="color" value={settings.accent} onChange={e=>updateSetting('accent',e.target.value)}/><code>{settings.accent}</code></div></label><label className="cc-field"><span>Font family</span><select value={settings.font} onChange={e=>updateSetting('font',e.target.value)}><option>Inter</option><option>System UI</option><option>Georgia</option><option>Arial</option><option>Manrope</option><option>DM Sans</option><option>Space Grotesk</option></select></label></div><div className="cc-field-grid"><label className="cc-field"><span>Background</span><div className="cc-color-field"><input type="color" value={settings.background} onChange={e=>updateSetting('background',e.target.value)}/><code>{settings.background}</code></div></label><label className="cc-field"><span>Surface color</span><div className="cc-color-field"><input type="color" value={settings.surface} onChange={e=>updateSetting('surface',e.target.value)}/><code>{settings.surface}</code></div></label></div><label className="cc-field"><span>Card corner radius · {settings.radius}px</span><input type="range" min="4" max="32" value={settings.radius} onChange={e=>updateSetting('radius',Number(e.target.value))}/></label><Field label="Homepage hero heading" value={settings.headerText} onChange={v=>updateSetting('headerText',v)}/><Field label="Footer message" value={settings.footerText} onChange={v=>updateSetting('footerText',v)}/></Panel><Panel title="Template manager" description="Save a named preset and switch between local previews." action={<button className="cc-btn-secondary small" onClick={()=>{const name=`Custom theme ${templates.length+1}`;setTemplates(t=>[...t,name]);setActiveTemplate(name);logAction(`Created theme template: ${name}`)}}><Plus size={14}/> Save template</button>}><div className="cc-template-list">{templates.map((t,i)=><button key={t} className={cn('cc-template',activeTemplate===t&&'selected')} onClick={()=>{setActiveTemplate(t);if(i===0){setSettings(s=>({...s,accent:'#9b87ff',background:'#08080b',surface:'#121218',radius:16}))}else if(i===1){setSettings(s=>({...s,accent:'#4f7cff',background:'#0b1018',surface:'#111b29',radius:10}))}else if(i===2){setSettings(s=>({...s,accent:'#d4a66a',background:'#100e0c',surface:'#201b17',radius:22}))}logAction(`Switched preview template: ${t}`)}}><span className="cc-template-swatch" style={{background:i===1?'#4f7cff':i===2?'#d4a66a':'#9b87ff'}}/><span><b>{t}</b><small>{i===0?'Dark glass / signature':i===1?'Clean / compact':'Editorial / warm'}</small></span>{activeTemplate===t&&<Check size={16}/>}</button>)}</div><div className="cc-note">A/B testing and drag-and-drop page composition require a connected backend and published template renderer; this panel currently switches visual presets for preview.</div></Panel></div><div className="cc-stack"><Panel title="Live design canvas" description="Preview of your current palette and radius."><div className="cc-theme-canvas" style={{background:settings.background,borderRadius:settings.radius}}><div className="cc-theme-top"><div className="cc-theme-logo" style={{background:settings.accent}}>✦</div><strong style={{fontFamily:settings.font}}>{settings.siteName}</strong><span>Tools&nbsp;&nbsp; Resources&nbsp;&nbsp; Pricing</span></div><div className="cc-theme-main"><span className="cc-theme-eyebrow" style={{color:settings.accent}}>THE UTILITY WORKSPACE</span><h3 style={{fontFamily:settings.font}}>{settings.headerText}</h3><p>{settings.tagline}</p><button style={{background:settings.accent}}>Explore tools <ArrowUpRight size={14}/></button><div className="cc-theme-tool-grid">{['Image Compressor','PDF Toolkit','Text Studio'].map((x,i)=><div key={x} style={{background:settings.surface,borderRadius:settings.radius,borderColor:settings.accent+'44'}}><span style={{color:settings.accent}}>{['◈','▤','⌘'][i]}</span><b>{x}</b><small>Fast, simple, in your browser</small></div>)}</div></div></div></Panel><Panel title="Custom CSS" description="CSS preview only. Saved to this browser, not injected into the live site."><textarea className="cc-textarea cc-code" rows={8} value={settings.customCss} onChange={e=>updateSetting('customCss',e.target.value)} placeholder=".tool-card { border-radius: 18px; }"/><div className="cc-row-end"><span className="cc-muted"><Code2 size={13}/> {settings.customCss.length} characters</span><button className="cc-btn-secondary small" onClick={()=>{updateSetting('customCss','');setToast('Custom CSS cleared')}}><Trash2 size={13}/> Clear</button></div></Panel><Panel title="Brand assets" description="Choose a logo or favicon preview asset."><label className="cc-upload-box"><Upload size={20}/><b>Choose asset file</b><small>SVG, PNG, JPG · local preview only</small><input type="file" accept="image/*,.svg" onChange={e=>addAsset(e.target.files?.[0])}/></label></Panel></div></div></>}
    {active==='tools'&&<><PageIntro icon={Blocks} eyebrow="MODULE 02 / TOOL CONTROL" title="Tool & feature commander" subtitle="Search the 1,040-entry concept catalog and manage enablement, labels and basic limits."/><div className="cc-stats-strip"><div><strong>{catalogTools.length.toLocaleString()}</strong><span>Catalog concepts</span></div><div><strong>{catalogTools.filter(t=>t.live).length}</strong><span>Originally ready-marked</span></div><div><strong>{catalogTools.filter(t=>(toolOverrides[t.id]?.enabled??t.live)).length}</strong><span>Currently enabled</span></div><div><strong>{catalogTools.length-catalogTools.filter(t=>(toolOverrides[t.id]?.enabled??t.live)).length}</strong><span>Disabled / planned</span></div></div><div className="cc-tool-manager"><Panel title="Tool catalog" description="Select an entry to edit its admin metadata."><div className="cc-tool-filters"><label className="cc-search"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search tools or descriptions"/></label><select value={category} onChange={e=>setCategory(e.target.value)}><option>All categories</option>{categoryNames.map(c=><option key={c}>{c}</option>)}</select></div><div className="cc-tool-list">{visibleTools.slice(0,160).map(t=>{const o=toolOverrides[t.id]||{enabled:t.live,name:t.name,description:t.description,seoTitle:`${t.name} | TOOLIXA`,limitMb:25,formats:'JPG, PNG, WEBP'};return <button className={cn('cc-tool-row',selectedTool===t.id&&'selected')} key={t.id} onClick={()=>setSelectedTool(t.id)}><span className="cc-tool-symbol"><Blocks size={15}/></span><span className="cc-tool-row-main"><b>{o.name}</b><small>{t.category} · {t.live?'Ready-marked':'Planned concept'}</small></span><span className={cn('cc-status',o.enabled?'enabled':'disabled')}>{o.enabled?'Enabled':'Disabled'}</span></button>})}{visibleTools.length===0&&<div className="cc-empty-small">No tools match this search.</div>}{visibleTools.length>160&&<div className="cc-note">Showing first 160 matching entries. Refine the search to reach the rest of the catalog.</div>}</div></Panel><div className="cc-stack"><Panel title="Tool configuration" description={currentTool.name}><div className="cc-tool-edit-head"><div className="cc-tool-symbol large"><WandSparkles size={20}/></div><div><b>{currentOverride.name}</b><small>{currentTool.id}</small></div><Toggle value={currentOverride.enabled} onChange={v=>{setToolOverrides(o=>({...o,[selectedTool]:{...currentOverride,enabled:v}}));logAction(`${v?'Enabled':'Disabled'} tool ${currentOverride.name}`)}}/></div><Field label="Display name" value={currentOverride.name} onChange={v=>setToolOverrides(o=>({...o,[selectedTool]:{...currentOverride,name:v}}))}/><label className="cc-field"><span>Description</span><textarea rows={3} value={currentOverride.description} onChange={e=>setToolOverrides(o=>({...o,[selectedTool]:{...currentOverride,description:e.target.value}}))}/></label><Field label="SEO title" value={currentOverride.seoTitle} onChange={v=>setToolOverrides(o=>({...o,[selectedTool]:{...currentOverride,seoTitle:v}}))}/><div className="cc-field-grid"><label className="cc-field"><span>Max file size (MB)</span><input type="number" min={1} max={500} value={currentOverride.limitMb} onChange={e=>setToolOverrides(o=>({...o,[selectedTool]:{...currentOverride,limitMb:Math.min(500,Math.max(1,Number(e.target.value)||1))}}))}/></label><label className="cc-field"><span>Allowed formats</span><input value={currentOverride.formats} onChange={e=>setToolOverrides(o=>({...o,[selectedTool]:{...currentOverride,formats:e.target.value}}))}/></label></div><button className="cc-btn-primary full" onClick={()=>saveNotice(`Tool metadata saved locally: ${currentOverride.name}`)}><Save size={14}/> Save tool configuration</button><div className="cc-note"><AlertTriangle size={14}/> Saved tool overrides are reflected by the public catalog when PostgreSQL is configured. Only tools already implemented in the code can be enabled; planned concepts remain unavailable.</div></Panel><Panel title="Create a custom tool" description="Define a draft tool specification for future implementation."><Field label="New tool name" value={newPageTitle} onChange={setNewPageTitle} placeholder="e.g. Image Background Cleaner"/><label className="cc-field"><span>Input type</span><select><option>Image</option><option>Video</option><option>PDF</option><option>Text</option><option>File / ZIP</option><option>URL</option></select></label><label className="cc-field"><span>Processing engine</span><select><option>Browser / Canvas</option><option>WASM module</option><option>Internal API</option><option>External API (requires credentials)</option></select></label><button className="cc-btn-secondary full" onClick={()=>{if(!newPageTitle.trim()){setToast('Enter a draft tool name');return}setToast('Custom tool specs need a server-side tool registry to become executable');logAction(`Custom tool spec requested: ${newPageTitle}`)}}><Plus size={14}/> Create draft specification</button></Panel></div></div></>}
    {active==='content'&&<><PageIntro icon={FileText} eyebrow="MODULE 03 / PUBLISHING" title="Page & content architect" subtitle="Manage page records, draft content and navigation planning."/><div className="cc-two-col"><Panel title="Pages manager" description="Edit the page inventory. Changes here are draft records only." action={<span className="cc-mini-count">{pages.length} pages</span>}><div className="cc-add-row"><input value={newPageTitle} onChange={e=>setNewPageTitle(e.target.value)} placeholder="New page title"/><button className="cc-btn-primary small" onClick={createPage}><Plus size={14}/> Add page</button></div><div className="cc-table-wrap"><table className="cc-table"><thead><tr><th>Page</th><th>Path</th><th>Status</th><th></th></tr></thead><tbody>{pages.map((p,i)=><tr key={p.slug+i}><td><b>{p.title}</b><small>{p.type}</small></td><td><code>{p.slug}</code></td><td><span className={cn('cc-status',p.status==='Published'?'enabled':'draft')}>{p.status}</span></td><td><button className="cc-mini-icon" title="Delete page" onClick={()=>{setPages(ps=>ps.filter((_,idx)=>idx!==i));logAction(`Removed page draft: ${p.title}`)}}><Trash2 size={14}/></button></td></tr>)}</tbody></table></div></Panel><div className="cc-stack"><Panel title="Blog post composer" description="Draft title and content locally."><Field label="Post title" value={postTitle} onChange={setPostTitle} placeholder="A useful guide to..."/><label className="cc-field"><span>Post body</span><textarea rows={8} value={postBody} onChange={e=>setPostBody(e.target.value)} placeholder="Write a draft. Rich publishing and scheduled posts need a connected CMS/database."/></label><div className="cc-field-grid"><label className="cc-field"><span>Publishing status</span><select><option>Draft</option><option>Review</option><option>Scheduled</option></select></label><label className="cc-field"><span>Category</span><select><option>Guides</option><option>Product updates</option><option>SEO</option><option>News</option></select></label></div><button className="cc-btn-primary full" onClick={()=>{if(!postTitle.trim()){setToast('Enter a post title');return}setPages(p=>[...p,{slug:'/blog/'+postTitle.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),title:postTitle,type:'Blog draft',status:'Draft'}]);logAction(`Created blog draft: ${postTitle}`);setToast('Blog draft added to page inventory')}}><BookOpen size={14}/> Save blog draft</button></Panel><Panel title="Navigation menus" description="Preview the main navigation labels."><div className="cc-menu-item"><span><Menu size={15}/> Header navigation</span><span>4 items <button onClick={()=>setToast('Menu editing is a planned server-backed capability')}>Edit</button></span></div><div className="cc-menu-item"><span><PanelLeft size={15}/> Footer navigation</span><span>6 items <button onClick={()=>setToast('Menu editing is a planned server-backed capability')}>Edit</button></span></div><div className="cc-menu-item"><span><Layers size={15}/> Tool categories</span><span>52 groups <button onClick={()=>setActive('tools')}>Manage</button></span></div></Panel></div></div></>}
    {active==='seo'&&<><PageIntro icon={ChartNoAxesCombined} eyebrow="MODULE 04 / DISCOVERY" title="SEO & marketing brain" subtitle="Configure global metadata and tracking identifiers. Publishing them to the live site requires backend wiring."/><div className="cc-two-col"><div className="cc-stack"><Panel title="Global search metadata" description="Default metadata values for the website."><Field label="Default meta title" value={settings.metaTitle} onChange={v=>updateSetting('metaTitle',v)}/><label className="cc-field"><span>Meta description · {settings.metaDescription.length}/160</span><textarea rows={3} maxLength={320} value={settings.metaDescription} onChange={e=>updateSetting('metaDescription',e.target.value)}/></label><Field label="Canonical base URL" value={settings.canonical} onChange={v=>updateSetting('canonical',v)}/><label className="cc-field"><span>Robots policy</span><select value={settings.robots} onChange={e=>updateSetting('robots',e.target.value)}><option>index, follow</option><option>noindex, follow</option><option>noindex, nofollow</option></select></label><label className="cc-field"><span>Default JSON-LD schema</span><textarea rows={4} defaultValue={'{\n  "@context": "https://schema.org",\n  "@type": "WebApplication",\n  "name": "TOOLIXA"\n}'} className="cc-code"/></label><button className="cc-btn-primary full" onClick={()=>saveNotice('SEO configuration saved locally')}><Save size={14}/> Save SEO defaults</button></Panel><Panel title="Analytics integrations" description="Identifiers only. Scripts are not injected from this prototype."><Field label="Google Analytics 4 measurement ID" value={settings.analyticsId} onChange={v=>updateSetting('analyticsId',v)} placeholder="G-XXXXXXXXXX"/><Field label="Google AdSense publisher ID" value={settings.adsenseId} onChange={v=>updateSetting('adsenseId',v)} placeholder="ca-pub-xxxxxxxx"/><div className="cc-setting-row"><div><b>Enable ad placements</b><small>Header, between tools, result area</small></div><Toggle value={settings.adsEnabled} onChange={v=>updateSetting('adsEnabled',v)}/></div><div className="cc-note">Only configure analytics and advertising after adding consent, privacy disclosures and a secure server-side injection policy.</div></Panel></div><div className="cc-stack"><Panel title="Search snippet preview" description="Approximate preview using current default metadata."><div className="cc-serp"><small>{settings.canonical||'https://your-domain.example'}</small><h3>{settings.metaTitle||'Untitled page'}</h3><p>{settings.metaDescription||'Add a concise description for search results.'}</p></div><div className="cc-seo-meter"><span>Title length</span><div><i style={{width:`${Math.min(100,settings.metaTitle.length/60*100)}%`}}/></div><b>{settings.metaTitle.length}/60</b></div><div className="cc-seo-meter"><span>Description</span><div><i style={{width:`${Math.min(100,settings.metaDescription.length/160*100)}%`}}/></div><b>{settings.metaDescription.length}/160</b></div></Panel><Panel title="SEO action checklist" description="Before launching production."><Checklist items={['Verify the canonical production domain','Confirm every public route has unique metadata','Generate sitemap from actual published pages','Add valid JSON-LD and test it','Connect Google Search Console','Measure Core Web Vitals after deployment']}/></Panel></div></div></>}
    {active==='media'&&<><PageIntro icon={HardDrive} eyebrow="MODULE 05 / ASSET OPERATIONS" title="Media & storage vault" subtitle="Inspect local preview assets and plan a storage provider integration."/><div className="cc-two-col"><Panel title="Media library" description="Files selected here remain in this browser session; they are not uploaded to a server." action={<label className="cc-btn-primary small cc-file-button"><Upload size={14}/> Upload asset<input type="file" multiple accept="image/*,.svg,.pdf" onChange={e=>Array.from(e.target.files||[]).forEach(addAsset)}/></label>}><div className="cc-media-grid">{assets.map((a,i)=><div className="cc-media-card" key={a.name+i}><div className="cc-media-thumb">{a.url&&a.name.match(/\.(png|jpe?g|webp|gif|svg)$/i)?<img src={a.url} alt=""/>:<FileText size={27}/>}</div><b title={a.name}>{a.name}</b><small>{a.size}</small><button className="cc-mini-icon" onClick={()=>setAssets(xs=>xs.filter((_,idx)=>idx!==i))}><Trash2 size={14}/></button></div>)}{assets.length===0&&<label className="cc-media-empty"><ImageIcon size={27}/><b>Your media vault is empty</b><small>Choose an image or file to preview it here.</small><input type="file" multiple onChange={e=>Array.from(e.target.files||[]).forEach(addAsset)}/></label>}</div></Panel><div className="cc-stack"><Panel title="Storage provider" description="Choose intended architecture; provider connections are not configured."><label className="cc-field"><span>Storage driver</span><select><option>Local / browser prototype</option><option>AWS S3 (credentials required)</option><option>Cloudinary (credentials required)</option><option>S3-compatible storage</option></select></label><label className="cc-field"><span>Image compression quality · 82%</span><input type="range" min="20" max="100" defaultValue="82"/></label><div className="cc-setting-row"><div><b>Automatic image optimization</b><small>Requires upload pipeline</small></div><Toggle value={false} onChange={()=>setToast('Image optimization is not connected to a storage pipeline')}/></div><div className="cc-setting-row"><div><b>Delete temporary uploads</b><small>Scheduled cleanup job</small></div><Toggle value={false} onChange={()=>setToast('Cleanup job requires a server scheduler')}/></div></Panel><Panel title="Storage readiness" description="Production prerequisites."><Checklist items={['Choose provider and create private bucket','Configure server-side credentials','Set upload MIME and size limits','Add file retention and deletion rules','Protect user uploads with authorization']}/></Panel></div></div></>}
    {active==='security'&&<><PageIntro icon={ShieldCheck} eyebrow="MODULE 06 / ACCESS CONTROL" title="User & security command" subtitle="Design role policy and security requirements before enabling production access."/><div className="cc-warning-banner danger"><LockKeyhole size={19}/><div><strong>Admin authentication is not enabled</strong><p>This route is currently a client-side preview and must not be treated as a protected admin area. Add server-enforced authentication, authorization and session protection before deploying it publicly.</p></div><span className="cc-status disabled">Action required</span></div><div className="cc-two-col"><Panel title="Role & permission model" description="Prototype role matrix; no real user accounts are connected." action={<button className="cc-btn-secondary small" onClick={()=>{setRoles(r=>[...r,{name:`Custom role ${r.length+1}`,members:0,permissions:'Choose permissions'}]);logAction('Added a role definition')}}><Plus size={14}/> Add role</button>}><div className="cc-role-list">{roles.map((r,i)=><div className="cc-role" key={r.name}><div className="cc-role-icon"><Users size={17}/></div><div className="cc-role-info"><b>{r.name}</b><small>{r.permissions}</small></div><span className="cc-mini-count">{r.members} users</span><button className="cc-mini-icon" onClick={()=>{if(r.name==='Super Admin'){setToast('Super Admin role cannot be removed');return}setRoles(rs=>rs.filter((_,idx)=>idx!==i))}}><Trash2 size={14}/></button></div>)}</div></Panel><div className="cc-stack"><Panel title="Security policy checklist" description="Must be implemented server-side."><Checklist items={['NextAuth/Auth.js or equivalent session authentication','Role-based access checks in every admin API route','Password hashing and secure session cookies','Two-factor authentication for privileged accounts','Rate limiting and brute-force protection','CSRF, origin and input validation','Audit logging for sensitive actions','Secret keys stored only in server environment']}/></Panel><Panel title="Admin access policy" description="Requirements to wire into the real backend."><div className="cc-setting-row"><div><b>Two-factor authentication</b><small>Require for Super Admin</small></div><Toggle value={false} onChange={()=>setToast('2FA cannot be enabled until identity provider is connected')}/></div><div className="cc-setting-row"><div><b>IP allowlist</b><small>Restrict administrative network access</small></div><Toggle value={false} onChange={()=>setToast('IP allowlist requires server middleware')}/></div><div className="cc-setting-row"><div><b>Tool usage rate limits</b><small>Per account / IP / day</small></div><Toggle value={false} onChange={()=>setToast('Rate limits require a shared server-side counter')}/></div></Panel></div></div></>}
    {active==='monetization'&&<><PageIntro icon={CreditCard} eyebrow="MODULE 07 / REVENUE CONTROL" title="Monetization & limits engine" subtitle="Draft plans and usage policies. No payments or subscriptions are connected."/><div className="cc-two-col"><Panel title="Pricing plan builder" description="Edit draft plan prices and visibility." action={<button className="cc-btn-secondary small" onClick={()=>setPlans(p=>[...p,{name:`Plan ${p.length+1}`,price:'0.00',period:'month',enabled:false}])}><Plus size={14}/> Add plan</button>}><div className="cc-plan-list">{plans.map((p,i)=><div className="cc-plan-card" key={p.name}><div className="cc-plan-card-top"><div><b>{p.name}</b><small>{p.enabled?'Visible in preview':'Hidden in preview'}</small></div><Toggle value={p.enabled} onChange={v=>setPlans(ps=>ps.map((x,idx)=>idx===i?{...x,enabled:v}:x))}/></div><div className="cc-plan-price"><span>$</span><input value={p.price} onChange={e=>setPlans(ps=>ps.map((x,idx)=>idx===i?{...x,price:e.target.value}:x))}/><select value={p.period} onChange={e=>setPlans(ps=>ps.map((x,idx)=>idx===i?{...x,period:e.target.value}:x))}><option value="month">/ month</option><option value="year">/ year</option><option value="once">one-time</option></select></div><small className="cc-muted">Price edits are drafts; checkout and billing are not connected.</small></div>)}</div></Panel><div className="cc-stack"><Panel title="Usage limits" description="Defaults for future server-side enforcement."><label className="cc-field"><span>Free operations per user per day</span><input type="number" min="0" max="10000" value={settings.freeDailyLimit} onChange={e=>updateSetting('freeDailyLimit',Math.max(0,Number(e.target.value)||0))}/></label><label className="cc-field"><span>Maximum upload size · MB</span><input type="number" min="1" max="5000" value={settings.maxUploadMb} onChange={e=>updateSetting('maxUploadMb',Math.min(5000,Math.max(1,Number(e.target.value)||1)))}/></label><div className="cc-note"><AlertTriangle size={14}/> These values do not enforce limits on public tools until the processing APIs validate them server-side.</div></Panel><Panel title="Payment provider" description="Connect only after adding server-side webhook verification."><div className="cc-provider-row"><span className="cc-provider-logo">S</span><div><b>Stripe</b><small>Cards, subscriptions, webhooks</small></div><span className="cc-status disabled">Not connected</span></div><div className="cc-provider-row"><span className="cc-provider-logo paddle">P</span><div><b>Paddle</b><small>Merchant of record option</small></div><span className="cc-status disabled">Not connected</span></div><button className="cc-btn-secondary full" onClick={()=>setToast('Payment providers require account credentials, server endpoints and webhook validation')}>View integration requirements <ArrowUpRight size={14}/></button></Panel></div></div></>}
    {active==='system'&&<><PageIntro icon={Database} eyebrow="MODULE 08 / RELIABILITY" title="System & backup core" subtitle="Export and restore browser configuration, inspect activity and review deployment controls."/><div className="cc-stats-grid"><Metric icon={Activity} label="Activity records" value={logs.length.toString()} delta="Current browser workspace"/><Metric icon={HardDrive} label="Local media items" value={assets.length.toString()} delta="Not server-stored"/><Metric icon={Database} label="Database" value="Not connected" delta="PostgreSQL schema included" warning/><Metric icon={Gauge} label="Maintenance mode" value={settings.maintenance?'Enabled':'Disabled'} delta="Preview setting only"/></div><div className="cc-two-col"><div className="cc-stack"><Panel title="Backup & restore" description="Backup covers the settings currently held in this browser, not server database or uploaded files."><div className="cc-backup-actions"><button className="cc-btn-primary" onClick={exportBackup}><Download size={15}/> Download JSON backup</button><label className="cc-btn-secondary cc-file-button"><Upload size={15}/> Restore backup<input type="file" accept="application/json,.json" onChange={e=>importBackup(e.target.files?.[0])}/></label></div><div className="cc-note">Never restore an untrusted JSON backup into a production control plane without schema validation and authorization.</div></Panel><Panel title="Runtime controls" description="These toggles do not yet alter production server behavior."><div className="cc-setting-row"><div><b>Maintenance mode</b><small>Show a maintenance page to visitors</small></div><Toggle value={settings.maintenance} onChange={v=>{updateSetting('maintenance',v);logAction(`Maintenance mode ${v?'enabled':'disabled'} in preview`)}}/></div><div className="cc-setting-row"><div><b>Clear local admin state</b><small>Remove settings from this browser</small></div><button className="cc-btn-danger small" onClick={()=>{if(confirm('Reset local Command Center settings?')){localStorage.removeItem(STORE_KEY);setSettings(defaultSettings);setToolOverrides(baseToolOverrides());setPages(initialPages);setTemplates(['Midnight / Default','Clean / Minimal','Studio / Editorial']);setActiveTemplate('Midnight / Default');setRoles([{name:'Super Admin',members:1,permissions:'Full access'},{name:'Editor',members:0,permissions:'Content, media, SEO'},{name:'Blogger',members:0,permissions:'Own posts only'}]);setPlans([{name:'Free',price:'0',period:'month',enabled:true},{name:'Pro',price:'4.99',period:'month',enabled:false},{name:'Studio',price:'9.99',period:'month',enabled:false}]);setLogs([]);setToast('Local state reset')}}}><RefreshCw size={13}/> Reset</button></div><div className="cc-setting-row"><div><b>Build cache</b><small>Netlify / Next.js cache</small></div><button className="cc-btn-secondary small" onClick={()=>setToast('Cache clearing must be done through your hosting provider or deployment pipeline')}>Instructions</button></div></Panel></div><Panel title="Activity log" description="Most recent actions performed in this browser session." action={<button className="cc-btn-secondary small" onClick={()=>{setLogs([]);setToast('Local activity log cleared')}}><Trash2 size={13}/> Clear log</button>}><div className="cc-log-list">{logs.map((l,i)=><div className="cc-log-row" key={i}><span className="cc-log-dot"/><div><b>{l.message}</b><small>{l.time}</small></div><span className="cc-status draft">{l.type}</span></div>)}{logs.length===0&&<div className="cc-empty-small">No activity yet. Settings changes and admin actions will be listed here.</div>}</div></Panel></div></>}
    {active==='integrations'&&<><PageIntro icon={Zap} eyebrow="MODULE 10 / CONNECTIONS" title="Integration control plane" subtitle="Inventory integrations and environment variables needed for a real SaaS deployment."/><div className="cc-integration-grid">{[{icon:Database,title:'PostgreSQL',desc:'Persistent users, settings, plans and logs',state:'Schema prepared'},{icon:Fingerprint,title:'Authentication',desc:'Admin sessions, OAuth and role checks',state:'Not connected'},{icon:CreditCard,title:'Stripe / Paddle',desc:'Checkout, subscriptions and signed webhooks',state:'Not connected'},{icon:HardDrive,title:'Object storage',desc:'Private file uploads and lifecycle rules',state:'Not connected'},{icon:ChartNoAxesCombined,title:'Analytics',desc:'GA4 events and privacy consent',state:settings.analyticsId?'ID entered':'Not connected'},{icon:Code2,title:'Custom scripts',desc:'Safe allowlisted snippets and CSP policy',state:'Not connected'},{icon:KeyRound,title:'API keys',desc:'Scoped keys, hashes, rotation and revocation',state:'Not implemented'},{icon:CalendarClock,title:'Scheduled jobs',desc:'Publishing, cleanup, reports and backups',state:'Not connected'}].map((it,i)=>{const Icon=it.icon;return <div className="cc-integration-card" key={it.title}><div className="cc-integration-icon"><Icon size={19}/></div><b>{it.title}</b><p>{it.desc}</p><div><span className={cn('cc-live-dot',i===0&&'soft')}/>{it.state}</div><button onClick={()=>setToast(`${it.title}: configuration is not connected in this prototype`)}>Configure <ChevronRight size={14}/></button></div>})}</div><Panel title="Environment variable checklist" description="Add secrets in Netlify Site configuration, never in browser code or committed files."><div className="cc-env-table"><div><code>DATABASE_URL</code><span>PostgreSQL connection string</span><b>Required</b></div><div><code>AUTH_SECRET</code><span>Session encryption secret</span><b>Required</b></div><div><code>NEXTAUTH_URL</code><span>Canonical production URL (if using NextAuth)</span><b>Auth</b></div><div><code>STRIPE_SECRET_KEY</code><span>Server-only billing secret</span><b>Optional</b></div><div><code>STRIPE_WEBHOOK_SECRET</code><span>Verify payment webhook signatures</span><b>Optional</b></div><div><code>OBJECT_STORAGE_*</code><span>Private storage credentials</span><b>Optional</b></div></div></Panel></>}
   </div>
   <footer className="cc-footer"><span>TOOLIXA COMMAND CENTER <b>•</b> LIVE OPERATIONS BRIDGE</span><span><span className="cc-live-dot"/> Database or local fallback <span className="cc-footer-sep">·</span> V3.1.0</span></footer>
  </section>
  {toast&&<motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0}} className="cc-toast"><CircleCheck size={17}/>{toast}<button onClick={()=>setToast('')}><X size={14}/></button></motion.div>}
 </main>
}
function Metric({icon:Icon,label,value,delta,warning}:{icon:any;label:string;value:string;delta:string;warning?:boolean}){return <div className="cc-metric"><div className="cc-metric-top"><span className="cc-metric-icon"><Icon size={17}/></span><span className={cn('cc-metric-indicator',warning&&'warning')}>{warning?<AlertTriangle size={13}/>:<ArrowUpRight size={13}/>}</span></div><strong>{value}</strong><b>{label}</b><small>{delta}</small></div>}
function PageIntro({icon:Icon,eyebrow,title,subtitle}:{icon:any;eyebrow:string;title:string;subtitle:string}){return <div className="cc-page-intro module"><div><div className="cc-kicker"><Icon size={13}/>{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div><span className="cc-module-chip"><Sparkles size={13}/> CONTROL MODULE</span></div>}
function Checklist({items}:{items:string[]}){return <div className="cc-checklist">{items.map((item,i)=><div key={item}><span className="cc-check-icon"><Check size={12}/></span><span>{item}</span><span className="cc-check-status">{i===0?'Review':'Pending'}</span></div>)}</div>}
